template.css:
.stop-btn {
  background: linear-gradient(135deg, #ff0044, #cc0033);
  color: #fff;
  border: 2px solid #ff0044;
  border-radius: 8px;
  padding: 12px 24px;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.2s;
}
.stop-btn:hover {
  box-shadow: 0 0 20px rgba(255, 0, 68, 0.5);
  transform: scale(1.05);
}
.stop-btn:active {
  transform: scale(0.95);
}
.stop-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

template.js:
function initStopButton(element, config) {
  element.addEventListener('click', () => {
    if (config.confirmRequired) {
      if (confirm(`Stop ${config.equipmentName}?`)) {
        writeTag(config.writeTag, config.writeValue);
      }
    } else {
      writeTag(config.writeTag, config.writeValue);
    }
  });
}
